import { Component, OnInit } from '@angular/core';
import { CharacterService } from '../../service/character.service';
import { ActivatedRoute, Router } from '@angular/router';
import { CharacterForm } from '../../model/character-form';
import { ProfessionService } from "../../../profession/service/profession.service";
import { Professions } from "../../../profession/model/professions";

@Component({
  selector: 'app-character-edit',
  templateUrl: './character-edit.component.html',
  styleUrls: ['./character-edit.component.css']
})
export class CharacterEditComponent implements OnInit {

  /**
   * Character's id.
   */
  uuid: string | undefined;

  /**
   * Single character.
   */
  character: CharacterForm | undefined;

  /**
   * Single character.
   */
  original: CharacterForm | undefined;

  /**
   * Available professions.
   */
  professions: Professions | undefined;

  /**
   * @param characterService character service
   * @param professionService profession service
   * @param route activated route
   * @param router router
   */
  constructor(
    private characterService: CharacterService,
    private professionService: ProfessionService,
    private route: ActivatedRoute,
    private router: Router
  ) {
  }

  ngOnInit() {
    this.route.params.subscribe(params => {
      this.professionService.getProfessions()
        .subscribe(professions => this.professions = professions);

      this.characterService.getCharacter(params['uuid'])
        .subscribe(character => {
          this.uuid = character.id;
          this.character = {
            name: character.name,
            background: character.background,
            age: character.age,
            charisma: character.charisma,
            constitution: character.constitution,
            strength: character.strength,
            profession: character.profession.id
          };
          this.original = {...this.character};
        });
    });
  }

  /**
   * Updates character.
   */
  onSubmit(): void {
    this.characterService.putCharacter(this.uuid!, this.character!)
      .subscribe(() => this.router.navigate(['/characters']));
  }

}
<article *ngIf="character">
  <header><h2>Edit character</h2></header>

  <form class="container"  #form="ngForm" (ngSubmit)="onSubmit()">
    <div class="row">
      <div class="col-4 p-2">
        <div>
          <label for="name">Name:</label>
          <input id="name" name="name" [(ngModel)]="character.name"/>
        </div>
      </div>
    </div>

    <div class="row">
      <div class="col-4 p-2">
        <div>
          <label for="age">Age:</label>
          <input id="age" name="age" [(ngModel)]="character.age"/>
        </div>
      </div>
    </div>

    <div class="row">
      <div class="col-4 p-2">
        <div>
          <label for="background">Background:</label>
          <textarea id="background" name="background" [(ngModel)]="character.background"></textarea>
        </div>
      </div>
    </div>

    <div class="row">
      <div class="col-4 p-2">
        <div>
          <label for="constitution">Constitution:</label>
          <input id="constitution" name="constitution" [(ngModel)]="character.constitution"/>
        </div>
      </div>
    </div>

    <div class="row">
      <div class="col-4 p-2">
        <div>
          <label for="strength">Strength:</label>
          <input id="strength" name="strength" [(ngModel)]="character.strength"/>
        </div>
      </div>
    </div>

    <div class="row">
      <div class="col-4 p-2">
        <div>
          <label for="charisma">Charisma:</label>
          <input id="charisma" name="charisma" [(ngModel)]="character.charisma"/>
        </div>
      </div>
    </div>

    <div class="row">
      <div class="col-4 p-2">
        <fieldset *ngIf="professions">
          <legend>Profession:</legend>
          <div *ngFor="let profession of professions.professions">
            <label>
              <input type="radio" name="profession" [(ngModel)]="character.profession" [value]="profession.id"/>
              {{profession.name}}
            </label>
          </div>
        </fieldset>
      </div>
    </div>

    <div class="row">
      <div class="col-2 p-2">
        <button type="submit">Update</button>
      </div>
      <div class="col-2 p-2">
        <button type="button" (click)="form.resetForm(original)">Reset</button>
      </div>
    </div>
  </form>
</article>
